import 'package:flutter/material.dart';
import '../services/profile_service.dart';
class OffersScreen extends StatelessWidget { const OffersScreen({super.key}); @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Offers & Coupons')),body:StreamBuilder(stream:ProfileService().coupons(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(12),children:s.data!.docs.map((d){final x=d.data();return Card(child:ListTile(title:Text(d.id,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${x['discountType']=='percent'?x['discountValue'].toString()+'%':'₹'+x['discountValue'].toString()} discount'),trailing:IconButton(icon:const Icon(Icons.copy),onPressed:()=>ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('${d.id} copied')))));}).toList());})); }
